"use strict";

import RoomHelper from "../roomHelper"
import { NetCityModalController } from "approot/global/controllers/netcityModalCtrl";

class AddRoomController extends NetCityModalController {
	constructor($scope, roomsRepository, $uibModalInstance, $dialogs, changeTracker, rooms, staffs, floors){
		super($scope, $uibModalInstance, changeTracker, $dialogs);
		
		this.roomsRepository = roomsRepository;
		this.$uibModalInstance = $uibModalInstance;
		this.language = language;

		this.header = language.Calendar.kAddRoom;

		this.data = {
			room: { study: true },
			rooms: rooms,
			staffs: staffs,
			floors: floors
		};

		this.state = {
			dataReady: true,
			viewReady: true
		};

		this.helpers = {
			roomHelper: new RoomHelper()
		}
	}

	create(valid) {
		if (valid) {
			let room = this.data.room;

			this.roomsRepository.create(room)
				.then((saved) => { this.$uibModalInstance.close(saved); });
		}
	}

	cancel() {
		this.$uibModalInstance.dismiss('cancel');
	}
}
AddRoomController.$inject = ["$scope", "roomsRepository", "$uibModalInstance", "$dialogs", "changeTracker", "rooms", "staffs", "floors"];

angular
	.module("irtech.netcity.school.classmanagement")
	.controller("AddRoomCtrl", AddRoomController)
	.directive("roomname", () => {
		return {
			restict: "A",
			require: "ngModel",
			scope: {
				rooms: "="
			},
			link: (scope, elm, attrs, ctrl) => {
				ctrl.$validators.roomname = function(modelValue, viewValue) {
					if (ctrl.$isEmpty(modelValue)) {
						return true;
					}

					return !_.chain(scope.rooms)
						.some((checkRoom) => {
							return trimStr(checkRoom.roomname) === elm.val();
						})
						.value();
				};
			}
		}
	});


