const module = angular.module("irtech.netcity.school.classmanagement",
	[
		"ngRoute", "ngSanitize", "ngMessages", "ui.select", "uikit.alerts", "uikit.dialogs", "ui.bootstrap",
		"irtech.netcity.common", "ngFileUpload", "ui.tree", "irtech.netcity.ui-components",
		"irtech.netcity.directive"
	]);

import { RoomsRepository } from "./repository.js";
import { UsersRepository } from "approot/school/users/repository.js";

import { AddProgramsComponent } from "./addPrograms/list/addPrograms.component";
import { AddProgramsRepository } from "./addPrograms/addPrograms.repository";

import { EditAddProgramComponent } from "./addPrograms/edit/editAddProgram.component";
import { ReferencesRepository } from "approot/global/repository/repositories";

require("./classes/classListCtrl.js");

require("./rooms/roomsCtrl.js");
require("./rooms/addRoom/addRoomCtrl.js");
require("./rooms/mergeRooms/mergeRoomsCtrl.js");

require("approot/global/directives/storageDirective.coffee");

/*@ngInject*/
let config = ($routeProvider, $locationProvider) => {
	$routeProvider
		.when("/classes", {
			templateUrl: "/static/dist/app/school/classmanagement/list/template.html",
			controller: "ClassesListCtrl"
		})
		.when("/rooms", {
			templateUrl: "/static/dist/app/school/classmanagement/rooms/template.html",
			controller: "RoomsListCtrl"
		})
		.when("/addprograms/", {
			templateUrl: AddProgramsComponent.templateUrl,
			controller: AddProgramsComponent.controller,
			controllerAs: "$ctrl"
		})
		.when("/addprograms/:programId", {
			templateUrl: EditAddProgramComponent.templateUrl,
			controller: EditAddProgramComponent.controller,
			controllerAs: "$ctrl"
		})
		//.when("/subjectGroups", {
		//	templateUrl: "/static/dist/app/school/classmanagement/subjectGroups/template.html",
		//	controller: "SubjectGroupsListCtrl"
		//})
		.otherwise({
			redirectTo: "/list"
		});

	$locationProvider.hashPrefix('');
	$locationProvider.html5Mode({
		enabled: true,
		requireBase: true
	});
};

module
	.filter('yesEmpty', () => {
		return (val) => {
			return val ? language.Generic.Common.kYes : "";
		}
	})
	.service("referencesRepository", ReferencesRepository)
	.service("roomsRepository", RoomsRepository)
	.service("addProgramsRepository", AddProgramsRepository)
	.component("addProgramsComponent", AddProgramsComponent)
	.component("editAddProgramComponent", EditAddProgramComponent)
	.service("usersRepository", UsersRepository)
	.config(config);



