"use strict";

import RoomHelper from "./roomHelper"

angular
	.module("irtech.netcity.school.classmanagement")
	.controller("RoomsListCtrl", ($scope, $http, $routeParams, $location, $appLoader, $uibModal, $q, $alerts, roomsRepository, usersRepository, changeTracker) => {

		$scope.$parent.page = {
			title: language.Calendar.kTitleRooms
		}

		$.extend($scope,
		{
			language: language,
			funcType: appContext.funcType,
			readonly: appContext.readOnly,
			state: {
				dataReady: false
			},
			data: {
				rooms: [],
				floors: [1, 2, 3, 4, 5, 6, 7, 8, 9],
				staffs: []
			},
			helpers: {
				roomHelper: new RoomHelper()
			}
		});

		// название "классы/объединения/группы" с заглавной буквы
		$scope.kClasses = language.SchoolSettings.kClasses
			.charAt(0)
			.toUpperCase() +
			language.SchoolSettings.kClasses.slice(1);

		// признак формирования нового года
		$scope.yearFormationMode = false;

		const addYearPostfix = (room) => {
			if (appContext.readOnly || !$scope.yearFormationMode) {
				return;
			}

			//todo. локализовать
			_.each(room.classes,
				(c) => {
					if (c.yearStatus === "Open") {
						c.name += " (Тек.)";
					} else if (c.yearStatus === "Future") {
						c.name += " (Буд.)";
					}
				});
		}

		// загрузка данных
		$scope.load = () => {
			// признак формирования нового года
			//todo. перенести в репозиторий
			const getYearFormationMode = $http.get("/webapi/years/yearFormationMode")
				.then((response) => {
					$scope.yearFormationMode = response.data;
				});

			const roomsReady = roomsRepository.getRooms(true)
				.then((rooms) => {
					$scope.data.rooms = _.map(rooms,
						(room) => {

							addYearPostfix(room);

							room.removable = false;
							room.storedName = room.roomname;
							room.classesStr = _.map(room.classes, (cls) => cls.name).join(", ");
							return room;
						});
				});

			const staffsReady = usersRepository.getStaffList()
				.then((staffs) => {
					$scope.data.staffs = staffs;
				});

			const queries = $q.all([getYearFormationMode, roomsReady, staffsReady]);

			queries.then(() => {
				$scope.notifyUserOfDuplicateTitles();
				$scope.state.dataReady = true;
				changeTracker.clearDataChanges();
				$appLoader.hide();
			});
		};

		// добавляет новое помещение
		const add = () => {
			if ($scope.helpers.roomHelper.hasSameRoomname($scope.data.rooms)) {
				return;
			}

			let modalInstance = $uibModal.open({
				templateUrl: "/static/dist/app/school/classes/rooms/addRoom/template.html",
				controller: "AddRoomCtrl as ctrl",
				resolve: {
					rooms: () => $scope.data.rooms,
					staffs: () => $scope.data.staffs,
					floors: () => $scope.data.floors
				}
			});
			modalInstance.result.then($scope.load);
		};
		$scope.add = _.debounce(add, 1500, true);

		// сливает помещения
		const merge = () => {
			if ($scope.helpers.roomHelper.hasSameRoomname($scope.data.rooms)) {
				return;
			}

			let modalInstance = $uibModal.open({
				templateUrl: "/static/dist/app/school/classes/rooms/mergeRooms/template.html",
				controller: "MergeRoomsCtrl",
				resolve: {
					rooms: () => $scope.data.rooms
				}
			});
			modalInstance.closed.then($scope.load);
			modalInstance.result.then($scope.load);
		};
		$scope.merge = _.debounce(merge, 1500, true);

		// удаляет помещения
		const remove = () => {
			if ($scope.helpers.roomHelper.hasSameRoomname($scope.data.rooms)) {
				return;
			}

			let ids = $scope.data.rooms.filter(r => r.removable).map(r => r.id);

			if (!ids.length) {
				alert(language.Calendar.kErrMsgNotChecked);
				return;
			}

			$.show.confirmation(language.Generic.Common.kMsgAreYouSure)
				.then(() => roomsRepository.remove(ids).then(() => {
					$scope.load();
					$alerts.success("успешное удаление");
				}));
		};
		$scope.remove = _.debounce(remove, 1500, true);

		// сохраняет помещения
		const save = (valid) => {
			if (!valid) {
				return;
			}
			if ($scope.helpers.roomHelper.hasSameRoomname($scope.data.rooms)) {
				return;
			}

			$.show.processing();
			roomsRepository.save($scope.data.rooms).then(() => {
				$scope.load();
				$alerts.success(language.Generic.Common.kDataSaved);
			});
		};
		$scope.save = _.debounce(save, 1500, true);

		// сбрасывает изменения на странице
		$scope.reset = _.debounce(() => {
			$appLoader.show();
			$scope.load();
		}, 1500, true);

		// пербрасывает на экран классы/объединения/группы
		$scope.goToClasses = () => {
			//todo. добавить подтверждение при наличии изменений на экране
			postTo("/asp/ClassManagement/Classes.asp");
		};

		// выводит предупреждающее сообщение об имеющихся дублях
		$scope.notifyUserOfDuplicateTitles = () => {
			let groups = _.groupBy($scope.data.rooms, (room) => trimStr(room.roomname));
			
			_.map($scope.data.rooms, (room) => {
				let key = trimStr(room.roomname);

				if (groups[key] && groups[key].length > 1) {
					room.duplicate = true;
				}
				else {
					room.duplicate = false;
				}
			});

			if ($scope.helpers.roomHelper.hasSameRoomname($scope.data.rooms)) {
				//todo. локализовать
				alert("Внимание! В поле 'Номер/название' имеются дублирующиеся значения. Необходимо отредактировать значения поля c соблюдением условия уникальности и нажать кнопку 'Сохранить'.");
			}
		};

		// отслеживает изменения в названиях помещений
		$scope.onChangeRoomName = (editRoom) => {
			let setRoomName = trimStr(editRoom.roomname);

			let existsSameRoomName = _.some($scope.data.rooms, (room) => room.id != editRoom.id && room.roomname == setRoomName);
			if (!existsSameRoomName) {
				return;
			}

			alert(language.Calendar.kMsgRoomExist).then(() => {
				editRoom.roomname = editRoom.storedName;
				$scope.$applyAsync(() => {});
			});
		};

		$scope.load();
	});


