import { AddProgramsRepository } from "../addPrograms.repository";
import { PageContext, AppContext } from "approot/global/services/context";
import { AppLoader } from "approot/global/apploader";
import { AddProgram, ProgDirection, ProgramLimit, AddProgramWithLimits } from "../addPrograms.model";
import { DialogsService, LongWorkService } from "approot/global/providers/uikit.dialogs";
import { AlertsService } from "approot/global/providers/uikit.alerts";
import * as Rights from "approot/global/references/rights.js";
import { NamedEntityDto } from "approot/global/models/common.model";
import { ReferencesRepository } from "approot/global/repository/repositories";
import { PfdoIntegrationType } from "approot/global/settingsProvider";

class AddProgramsControler {
	public state = {
		readOnly: true,
		dataReady: false,
		integrationPFDO: false,
		integrationPFDOType: null
	}

	private programs: AddProgram[];
	private limits: ProgramLimit[];

	public programsWithLimits: AddProgramWithLimits[];

	public directions: ProgDirection[];
	public directionId: number = -1;

	private selected: number[] = [];

	public years: any[];
	public yearId: number;

	public statuses: NamedEntityDto[];
	public status: number = 1;

	public rowSpan: any = {};

	/*@ngInject*/
	constructor(
		pageContext: PageContext,
		private $q,
		private $appLoader: AppLoader,
		private $dialogs: DialogsService,
		private $alerts: AlertsService,
		private $longWork: LongWorkService,
		private addProgramsRepository: AddProgramsRepository,
		private referencesRepository: ReferencesRepository,
		private contextService,
		appContext: AppContext,
		private $location,
		private settingsProvider,
		public language: any) {

		pageContext.title = language.Generic.SetupSchool.kTitleAddPrograms;
		pageContext.parent = null;

		let search = $location.search();

		this.yearId = parseInt(search.yearId || appContext.yearId);
		this.directionId = parseInt(search.directionId || -1);
		this.status = parseInt(search.status || 1);

		this.state.readOnly = !appContext.hasAnyRight([Rights.arClassMgmCreateClass])

		this.init();
	}

	init() {
		const loadPrograms = this.addProgramsRepository.getAll(this.directionId === -1 ? null : this.directionId, this.status).then((programs) => {
			this.programs = programs;
		});

		const loadProgramLimits = this.addProgramsRepository.getProgramLimits(this.yearId, this.directionId === -1 ? null : this.directionId, this.status).then((limits) => {
			this.limits = limits;
		})

		const loadYears = this.contextService.getYears().then((years) => {
			this.years = years;
			if (!this.state.readOnly) {
				this.state.readOnly = this.years.find((y) => y.id === this.yearId).closed === 'Closed';
			}
		});

		const loadDirections = this.addProgramsRepository.getProgDirections().then((directions) => {
			this.directions = directions;
			this.directions.unshift({ id: -1, name: this.language.Generic.Common.kAll, old: false, sortOrder: -1 });
		});

		const loadStatuses = this.referencesRepository.getProgramStatuses().then((statuses) => {
			this.statuses = statuses;
		});

		const loadIntegrationPFDOType = this.settingsProvider.ServerSettings.SystemSettings.IntegrationPFDOType().then((integration) => {
			this.state.integrationPFDOType = integration;
			this.state.integrationPFDO = integration == PfdoIntegrationType.Volgograd;
		});


		this.$q.all([loadPrograms, loadDirections, loadProgramLimits, loadYears, loadStatuses, loadIntegrationPFDOType]).then(() => {

			this.programsWithLimits = this.programs.map((p) => {
				let programLimits = this.limits.filter((l) => l.programId === p.id).sort((a, b) => a.grade > b.grade ? 1 : a.grade < b.grade ? -1 : 0);

				let progWithLimits: AddProgramWithLimits = {
					addProgram: p,
					limits: programLimits,
					addresses: null,
					schoolYearId: this.yearId
				};
				this.rowSpan[p.id] = programLimits.length == 0 ? 1 : programLimits.length;

				return progWithLimits;
			});

			if (this.state.integrationPFDO) {
				this.state.readOnly = true;
			}

			this.state.dataReady = true;
			this.$appLoader.hide();
		});
	}

	changeFilter() {
		this.$location.path("/addprograms").search({ yearId: this.yearId, directionId: this.directionId, status: this.status });
	}

	add() {
		if (this.state.readOnly) {
			return;
		}
		this.$location.path("/addprograms/new").search({ readOnly: this.state.readOnly, yearId: this.yearId });
	}

	edit(program: AddProgram) {
		this.$location.path("/addprograms/" + program.id).search({ readOnly: this.state.readOnly, yearId: this.yearId,  integrationPFDO: this.state.integrationPFDO});
	}

	remove() {
		if (this.selected.length === 0) {
			this.$dialogs.message(this.language.Generic.SetupSchool.kMsgNoSelectedPrograms);
			return;
		}
		//todo. процессинг
		this.$dialogs.confirmDelete(this.language.Generic.Common.kMsgAreYouSure).then(() => {
			this.$longWork.show();
			this.addProgramsRepository.remove(this.selected).then(() => {
				this.$longWork.close();

				this.selected = [];
				this.$alerts.success(this.language.Generic.Calendar.kMsgDeletedSuccess);

				this.$appLoader.show();
				this.init();
			});
		});
	}

	toggleChecks(id) {
		var idx = this.selected.indexOf(id);
		if (idx > -1) {
			this.selected.splice(idx, 1);
		}
		else {
			this.selected.push(id);
		}
	}
}

export const AddProgramsComponent = {
	controller: AddProgramsControler,
	templateUrl: "/static/dist/app/school/classmanagement/addprograms/list/addprograms.component.html"
}




