"use strict";

import { BaseRepository } from "approot/global/repository.js";

class RoomsRepository extends BaseRepository {
	getRooms(detailed, studyOnly) {
		let params = {};
		if (detailed) {
			params.detailed = true;
		}
		if (studyOnly) {
			params.studyOnly = true;
		}
		return this.$http.get("/webapi/rooms", { params: params})
			.then((response) => {
				return response.data;
			})
			.catch(this.handleError);
	}

	create(room) {
		return this.$http.put("/webapi/rooms", room)
			.then((response) => {
				this.$alerts.success(language.Calendar.kCreateRoomsSuccess);
				return response.data;
			})
			.catch(this.handleError);
	}

	merge(mergeRoomId, roomId) {
		let params = {
			mergeRoomId: mergeRoomId,
			roomId: roomId
		};

		return this.$http.post("/webapi/rooms/integrated", null, { params: params })
			.then((response) => {
				this.$alerts.success(language.Calendar.kMergeRoomsSuccess);
				return response.data;
			})
			.catch(this.handleError);
	}

	remove(ids) {
		let params = { id: ids };
		//todo. репозиторий не должен содержать такую логику (последовательность вызовов и подтверждения) - перенсти в контроллер

		return this.$http.get("/webapi/rooms/used", { params: params })
			.then((response) => {
				let usedRooms = response.data;

				if (usedRooms.length) {
					return $.show.confirmation(language.Calendar.kDeleteRoomsWarn);
				}

				return $.Deferred().resolve();
			})
			.then(() => {
				return this.$http.delete("/webapi/rooms", { params: params });
			})
			.catch(this.handleError);
	}

	save(rooms) {
		return this.$http.post("/webapi/rooms", rooms)
			.then(this.handleResponse)
			.catch(this.handleError);
	}
}

module.exports = { RoomsRepository };


