"use strict";

import { BaseRepository } from "approot/global/repository.js";

class UsersRepository extends BaseRepository {
	getStaffList(roles) {
		let params = {};
		if (roles) {
			params.role = roles;
		}
		return this.$http.get("/webapi/users/staff", { params: params })
			.then((response) => {
				return response.data;
			})
			.catch(this.handleError);
	}

	getTeacherList(subjectId, sgId) {
		let params = {};
		if (subjectId) {
			params.subjectId = subjectId;
		}
		if (sgId) {
			params.sgId = sgId;
		}

		return this.$http.get("/webapi/users/staff/teachers", { params: params })
			.then(this.handleResponse)
			.catch(this.handleError);
	}

	getFilterPanelForImportStaff() {
		let res = this.$http.get("/webapi/users/staff/import/filterpanel").catch(this.handleError);
		return res;
	}

	getStaffsForImport(schoolId) {
		let params = { schoolId };
		let res = this.$http.get("/webapi/users/staff/import/browse", { params }).catch(this.handleError);
		return res;
	}

	postReuseUsers(userIds, yearId) {
		//let res = this.$http.post("/webapi/users/staff/import/reuseStaff", userIds, { params: { yearId: yearId } }).catch(this.handleError);
		let res = this.$http.post("/webapi/users/staff/import/reuseStaff/?yearId=" + yearId, userIds).catch(this.handleError);
		return res;
	}
}

module.exports = { UsersRepository };


