"use strict";

import RoomHelper from "../roomHelper"

angular
	.module("irtech.netcity.school.classmanagement")
	.controller("MergeRoomsCtrl", ($scope, roomsRepository, $uibModalInstance, rooms, $controller, $dialogs, changeTracker) => {

		$scope.header = language.Calendar.kReplaceRoom;

		$.extend($scope, {
			language: language,
			data: {
				mergeRoomId: _.first(rooms).id,
				roomId: _.first(rooms).id,
				rooms: rooms
			},
			state: {
				dataReady: true,
				viewReady: true
			},
			helpers: {
				roomHelper: new RoomHelper()
			}
		});

		$scope.merge = () => {

			if ($scope.helpers.roomHelper.hasRoomWithHimself($scope.data.mergeRoomId, $scope.data.roomId)) {
				alert(language.Calendar.kMergeRoomWithHimself);
				return;
			}

			$.show.confirmation(language.Calendar.kMergeRoomsWarn).then(() => {
				roomsRepository.merge($scope.data.mergeRoomId, $scope.data.roomId)
					.then((saved) => {
						$uibModalInstance.close(saved);
					});
			});
		};

		$scope.cancel = () => {
			$uibModalInstance.dismiss('cancel');
		};
		$controller("NetCityModalController", { $scope, $dialogs, $uibModalInstance, changeTracker });
	});


