import { AddProgramsRepository } from "../addPrograms.repository";
import { LongWorkService } from "approot/global/providers/uikit.dialogs";
import { PageContext } from "approot/global/services/context";
import { AppLoader } from "approot/global/apploader";
import { AddProgramWithLimits, ProgDirection, ProgramLimit, AddActivityType, PfdoPublishStatus } from "../addPrograms.model";
import { NamedEntityDto } from "approot/global/models/common.model";
import { FileAttachmentsSettings } from "approot/global/components/fileattachments.component";
import { ReferencesRepository } from "approot/global/repository/repositories";
import { SettingsProvider, PfdoIntegrationType} from "approot/global/settingsProvider";

class EditAddProgramController {
	public state = {
		readOnly: true,
		createMode: false,
		editMode: false,
		dataReady: false,
		integrationIrtechPFDO: false
	}
	public programId: number;
	public yearId: number;
	public data: AddProgramWithLimits = null;
	public directions: ProgDirection[] = [];
	public programTypes: NamedEntityDto[];
	public programCosts: NamedEntityDto[];
	public programLimits: ProgramLimit[] = [];
	public ages: number[] = [];
	public durationYears: number[] = [];
	public durationMonths: number[] = [];

	public educForms: NamedEntityDto[];
	public activityTypes: AddActivityType[] = [];
	public statuses: NamedEntityDto[];

	public fa: FileAttachmentsSettings;
	public faImage: FileAttachmentsSettings;
	public faFullContent: FileAttachmentsSettings;

	public pfdoPublishStatus: PfdoPublishStatus = {status: "", extendStatus: "", statusDate: null};

	public addProgramForm: ng.IFormController;

	/*@ngInject*/
	constructor(
		pageContext: PageContext,
		private $appLoader: AppLoader,
		private $longWork: LongWorkService,
		private $alerts,
		private addProgramsRepository: AddProgramsRepository,
		private referencesRepository: ReferencesRepository,
		private $q,
		$routeParams,
		private $location,
		private changeTracker,
		private $scope: ng.IScope,
		private settingsProvider: SettingsProvider,
		public language: any
	) {

		pageContext.parent = {
			title: language.Generic.SetupSchool.kTitleAddPrograms,
			href: "/addprograms"
		};

		//todo. устанавливать заголовок согласно состоянию экрана. редактирование или создание программы доп. образования
		pageContext.title = language.Generic.SetupSchool.kTitleAddProgram;

		this.state.readOnly = ($routeParams.readOnly === true);

		if ($routeParams.programId === "new") {
			this.programId = 0;
			this.state.createMode = true;

			if (this.state.readOnly) {
				this.$alerts.error("Невозможно создать новую программу");
				this.$location.path("/addprograms/");
			}
		}
		else {
			this.programId = parseInt($routeParams.programId);
			this.state.editMode = true;
		}
		this.yearId = parseInt($routeParams.yearId);

		this.ages.push(null);
		for (var i = 5; i <= 18; i++) {
			this.ages.push(i);
		}

		this.durationYears.push(null);
		for (var i = 0; i <= 18; i++) {
			this.durationYears.push(i);
		}

		this.durationMonths.push(null);
		for (var i = 0; i <= 11; i++) {
			this.durationMonths.push(i);
		}

		this.makeEmptyLimits();

		this.init();
	}

	init() {
		//todo. load refs

		const loadDirections = this.addProgramsRepository.getProgDirections().then((directions) => {
			this.directions = directions;
		});

		const loadProgramTypes = this.referencesRepository.getProgramTypes().then((programTypes) => {
			this.programTypes = programTypes;
		});

		const loadProgramCosts = this.referencesRepository.getProgramCosts().then((programCosts) => {
			this.programCosts = programCosts;
			this.programCosts.unshift({ id: null, name: '' });
		});

		const loadEducForms = this.referencesRepository.getProgramEducForms().then((educForms) => {
			this.educForms = educForms;
		});

		const loadStatuses = this.referencesRepository.getProgramStatuses().then((statuses) => {
			this.statuses = statuses;
		});

		const loadActivityTypes = this.addProgramsRepository.getActivityTypes().then((activityTypes) => {
			this.activityTypes = activityTypes;
		});

		const loadProgramEdit = new Promise((resolve) => {
			if (!this.programId || this.programId <= 0) {
				resolve();
				return;
			}

			this.addProgramsRepository.getProgramEdit(this.programId, this.yearId).then((programData) => {
				this.data = programData;
				if (this.data.addProgram.cost === null) {
					this.data.addProgram.cost = { id: null, name: '' };
				}

				this.programLimits = this.programLimits.map((lim) => {
					var find = this.data.limits.find((dt) => dt.grade === lim.grade);
					return find === undefined ? lim : find;
				})
				
				if (this.data.addresses === null || this.data.addresses.length === 0) {
					this.data.addresses = [{id: 0, name: ''}];
				}

				this.settingsProvider.ServerSettings.SystemSettings.IntegrationPFDOType()
					.then((integration) => {
						this.state.integrationIrtechPFDO = (integration == PfdoIntegrationType.IRTechEes);
						resolve();
				});				
			})
		})

		const initFileAttachment = () => {
			const file = this.data.addProgram.attachment === null ? null : [this.data.addProgram.attachment];
			this.fa = {
				options: {
					readonly: this.state.readOnly,
					multiple: false,
					showDescription: true,
					uploadLimits: {
						fileSizeLimit: 8192 // 8192 / 1024 = 8 Мб
					}
				},
				data: {
					files: file || [],
					context: {
						addProgramAttachId: 1 // здесь реальное значение ид. не имеет значения, здесь как бы отмечаем поле
					}
				}
			}

			const fileImage = this.data.addProgram.image === null ? null : [this.data.addProgram.image];
			this.faImage = {
				options: {
					readonly: this.state.readOnly,
					multiple: false,
					showDescription: true,
					uploadLimits: {
						fileSizeLimit: 8192 // 8192 / 1024 = 8 Мб
					}
				},
				data: {
					files: fileImage || [],
					context: {
						addProgramImageId: 1 // здесь реальное значение ид. не имеет значения, здесь как бы отмечаем поле
					}
				}
			}

			const fileContent = this.data.addProgram.fullContent === null ? null : [this.data.addProgram.fullContent];
			this.faFullContent = {
				options: {
					readonly: this.state.readOnly,
					multiple: false,
					showDescription: true,
					uploadLimits: {
						fileSizeLimit: 8192 // 8192 / 1024 = 8 Мб
					}
				},
				data: {
					files: fileContent || [],
					context: {
						addProgramFullContentId: 1 // здесь реальное значение ид. не имеет значения, здесь как бы отмечаем поле
					}
				}
			}
		}

		var promises = (this.state.readOnly) ? [loadProgramEdit] : 
			[loadDirections, loadProgramTypes, loadProgramCosts, loadProgramEdit, loadEducForms, loadStatuses, loadActivityTypes];

		return this.$q.all(promises).then(() => {

			if (this.programId === 0) {
				this.data = {
					addProgram: {
						id: 0,
						name: "",
						shortName: "",
						description: "",
						adaptation: false,
						direction: this.directions[0],
						programType: this.programTypes[0],
						federalRequirements: "",
						artType: "",
						//useDistanceTech: false,
						target: "",
						result: "",
						materialBase: "",
						healthRequirements: "",
						ageMin: null,
						ageMax: null,
						cost: { id: null, name: '' },

						durationYear: null,
						durationMonth: null,
						educForm: this.educForms[0],
						activityType: this.activityTypes.filter(x => x.directionId === this.directions[0].id)[0],
						medReference: false,
						status: this.statuses[0],
						//status: { id: 1, name: 'Активная программа12' },
						keyWord: "",

						attachment: null,
						image: null,
						fullContent: null,
						seatsNumber: 0,

						pfdoNavId: "",
						pfdoNavDate: null,

						used: false
					},
					limits: [],
					addresses: [{ id: 0, name: '' }],
					schoolYearId: this.yearId
				}
			}
			else if (this.state.integrationIrtechPFDO && this.data.addProgram.pfdoNavId !== null && this.data.addProgram.pfdoNavId.length > 0) {
				this.addProgramsRepository.getPublishStatus(this.data.addProgram.id)
					.then((publishStatus) => {
						this.pfdoPublishStatus = {
							status: publishStatus.status,
							extendStatus: publishStatus.extendStatus,
							statusDate: publishStatus.statusDate
						};
					})
			}

			initFileAttachment();
			this.$scope.$applyAsync();
			this.$appLoader.hide();
			this.state.dataReady = true;
		});
	}

	makeEmptyLimits() {
		for (var i = 0; i <= 12; i++) {
			this.programLimits.push({ programId: this.programId, grade: i, weekHours: null, yearHours: null });
		}
	}

	reset() {
		this.state.dataReady = false;
		this.changeTracker.clearDataChanges();
		this.$appLoader.show();
		this.init().then(() => {
			this.$alerts.success(language.Generic.Common.kResetChanges);
		});
	}

	save() {
		let valid = this.addProgramForm.$valid && this.isAgeRangeValid();
		if (!valid) {
			return;
		}

		let invalidLimits = this.data.limits.filter(l => !this.isValidLimit(l));
		if (invalidLimits.length > 0) {
			return;
		}

		this.data.limits = this.programLimits.filter(x => x.weekHours >= 0.1);
		if (this.data.addProgram.cost && this.data.addProgram.cost.id === null) {
			this.data.addProgram.cost = null;
		}

		const mapFunc = (f) => ({ id: f.id });
		//this.data.addProgram.attachment = _.map(this.fa.data.files, mapFunc);
		this.data.addProgram.attachment = null;
		if (this.fa.data.files.length === 1) {
			this.data.addProgram.attachment = this.fa.data.files.map(mapFunc)[0];
		}

		this.data.addProgram.image = null;
		if (this.faImage.data.files.length === 1) {
			this.data.addProgram.image = this.faImage.data.files.map(mapFunc)[0];
		}

		this.data.addProgram.fullContent = null;
		if (this.faFullContent.data.files.length === 1) {
			this.data.addProgram.fullContent = this.faFullContent.data.files.map(mapFunc)[0];
		}

		this.data.addresses = this.data.addresses.filter(x => x.name.trim().length > 0);

		this.data.addProgram.seatsNumber = parseInt(this.data.addProgram.seatsNumber.toFixed(0));

		this.$longWork.show();
		if (this.programId > 0) {
			this.addProgramsRepository.save(this.data).then(
				() => {
					this.$longWork.close();
					this.$alerts.success(language.Generic.SetupAddSchool.kAddProgramEditSuccess);
					this.$location.path("/addprograms/");
				},
				() => {
					this.$longWork.close();
				}
			)
		}
		else {
			this.addProgramsRepository.create(this.data).then(
				() => {
					this.$longWork.close();
					this.$alerts.success(language.Generic.SetupAddSchool.kAddProgramCreateSuccess);
					this.$location.path("/addprograms/");
				},
				() => {
					this.$longWork.close();
				}			
			)
		}
	}

	publicate() {
		if (!this.state.integrationIrtechPFDO || !this.state.editMode) {
			return;
		}

		this.$longWork.show();
		this.addProgramsRepository.publicate(this.programId).then(
			(publishStatus) => {
				this.$longWork.close();
				this.$alerts.success("Программа отправлена на публикацию");
				this.pfdoPublishStatus = {status: publishStatus.status, extendStatus: publishStatus.extendStatus, statusDate: publishStatus.statusDate};
				this.data.addProgram.pfdoNavDate = publishStatus.statusDate;
				//this.$location.path("/addprograms/");
			},
			() => {
				this.$longWork.close();
			}			
		)

	}

	isAgeRangeValid() {
		if (this.state.readOnly) {
			return true;
		}

		if (!this.state.dataReady) {
			return true;
		}

		if (this.data === null) {
			return true;
		}

		if (!this.data.addProgram) {
			return true;
		}

		var ageMin = this.data.addProgram.ageMin;
		var ageMax = this.data.addProgram.ageMax;
		return (ageMin === null && ageMax === null) || (ageMin !== null && ageMax !== null && ageMin <= ageMax);

		//return this.checkNumbers(this.data.addProgram.ageMin, this.data.addProgram.ageMax);
	}

	isValidLimit(limit) {
		if (this.state.readOnly) {
			return true;
		}

		if (!this.state.dataReady) {
			return true;
		}

		var weekHours = limit.weekHours;
		var yearHours = limit.yearHours;
		return (weekHours === null && yearHours === null) || (weekHours !== null && yearHours === null) || (weekHours !== null && yearHours !== null && weekHours <= yearHours);

		//return this.checkNumbers(limit.weekHours, limit.yearHours);
	}

	// checkNumbers(num1?: number, num2?: number){
	// 	return (num1 === null && num2 === null) || (num1 !== null && num2 !== null && num1 <= num2);
	// }

	filterActivityTypesByDirection() {
		if (this.data === null) {
			return [];
		}

		if (!this.data.addProgram) {
			return [];
		}

		if (!this.data.addProgram.direction) {
			return [];
		}

		return this.activityTypes.filter(x => x.directionId === this.data.addProgram.direction.id);
	}

	onChangeDirection() {
		if (this.state.readOnly) {
			return;
		}

		this.data.addProgram.activityType = this.activityTypes.filter(x => x.directionId === this.data.addProgram.direction.id)[0];
	}

	addAddress() {
		if (this.state.readOnly) {
			return;
		}
		this.data.addresses.push({id: 0, name: ''});		
	}
}


export const EditAddProgramComponent = {
	controller: EditAddProgramController,
	templateUrl: "/static/dist/app/school/classmanagement/addprograms/edit/editAddProgram.component.html"
}



