import { BaseRepository } from "approot/global/repository/baseRepository";
import { AddProgram, ProgDirection, ProgramLimit, AddProgramWithLimits, AddActivityType, PfdoPublishStatus } from "./addPrograms.model";
import { NamedEntityDto, EnumItemDto } from "approot/global/models/common.model";

export class AddProgramsRepository extends BaseRepository{
	getAll(directionId?: number, status?: number) : Promise<AddProgram[]>{
		let params : any = {};
		if(directionId){
			params.directionId = directionId;
		}
		if(status){
			params.status = status;
		}
		return this.get("/webapi/addprograms", { params: params});
	}

	getProgramLimits(yearId: number, directionId?: number, status?: number) : Promise<ProgramLimit[]>{
		let params : any = {
			yearId: yearId
		};
		if(directionId){
			params.directionId = directionId;
		}
		if(status){
			params.status = status;
		}
		return this.get("/webapi/addprograms/limits", { params: params});
	}

	getProgramEdit(progId: number, yearId: number) : Promise<AddProgramWithLimits>{
		let params : any = {};
		params.yearId = yearId;
		return this.get("/webapi/addprograms/" + progId, { params: params});
	}

	create(program: AddProgramWithLimits) : Promise<AddProgramWithLimits>{
		return this.$http.put("/webapi/addprograms", program)
			.then(this.handleResponse, this.handleError);
	}

	save(program: AddProgramWithLimits) : Promise<AddProgramWithLimits>{
		return this.$http.post("/webapi/addprograms", program)
			.then(this.handleResponse, this.handleError);
	}

	publicate(programId: number) : Promise<PfdoPublishStatus>{
		return this.$http.post("/webapi/integration/pfdo/publishprogram?programId=" + programId)
			.then(this.handleResponse, this.handleError);
	}

	getPublishStatus(programId: number) : Promise<PfdoPublishStatus>{
		return this.$http.post("/webapi/integration/pfdo/programstatus?programId=" + programId)
			.then(this.handleResponse, this.handleError);
	}

	replace(id: number, to: number) : Promise<any>{
		//todo.
		return null;
	}

	remove(ids: number[]) : Promise<any>{
		return this.$http.delete("/webapi/addprograms", { params: { id: ids }})
			.then(this.handleResponse, this.handleError);
	}

	getProgDirections() : Promise<ProgDirection[]>{
		return this.get("/webapi/references/progdirections");
	}

	getActivityTypes() : Promise<AddActivityType[]>{
		return this.get("/webapi/references/addactivitytypes");
	}
}



